def validate_user(data):
    if 'username' not in data:
        return dict(failed=True, msg='No username specified')
    c_uid = os.getuid()
    try:
        t_uid = pwd.getpwnam(data['username']).pw_uid
    except:
        return dict(failed=True, msg='could not find user %s' % data['username'])
