def obtain_github_oauth():
    """
    https://developer.github.com/v3/oauth_authorizations/#create-a-new-authorization
    """
    api_headers = {"User-Agent": "edx-release"}
    api_payload = {"note": "edx-release"}
    user = raw_input("Github username: ")
    pwd = getpass.getpass("Github password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=api_headers, data=json.dumps(api_payload),
    )
    otp_hdr = resp.headers.get("X-GitHub-OTP")
    if not resp.ok and otp_hdr and otp_hdr.startswith("required;"):
        api_headers["X-GitHub-OTP"] = raw_input("Two-factor authentication code: ")
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=api_headers, data=json.dumps(api_payload),
        )
    if not resp.ok:
        err = resp.json()["message"]
        if err != "Validation Failed":
            return True
        else:
            token_id = get_github_auth_id(user, pwd, "edx-release")
            if token_id:
                delete_github_auth_token(user, pwd, token_id)
            resp = requests.post(
                "https://api.github.com/authorizations",
                auth=(user, pwd),
                headers=api_headers, data=json.dumps(api_payload),
            )
    if not resp.ok:
        err = resp.json()["message"]
        return True

    return (user, resp.json()["token"])

def kinit_keytab(principal, keytab, ccache_name, config=None, attempts=1):
    errors_to_retry = {KRB5KDC_ERR_SVC_UNAVAILABLE,
                       KRB5_KDC_UNREACH}
    root_logger.debug("Initializing principal %s using keytab %s"
                      % (principal, keytab))
    root_logger.debug("using ccache %s" % ccache_name)
    for attempt in range(1, attempts + 1):
        old_config = os.environ.get('KRB5_CONFIG')
        if config is not None:
            os.environ['KRB5_CONFIG'] = config
        else:
            os.environ.pop('KRB5_CONFIG', None)
        try:
            name = gssapi.Name(principal, gssapi.NameType.kerberos_principal)
            store = {'ccache': ccache_name,
                     'client_keytab': keytab}
            cred = gssapi.Credentials(name=name, store=store, usage='initiate')
            root_logger.debug("Attempt %d/%d: success"
                              % (attempt, attempts))
            return cred
        except gssapi.exceptions.GSSError as e:
            if e.min_code not in errors_to_retry:
                return True
            root_logger.debug("Attempt %d/%d: failed: %s"
                              % (attempt, attempts, e))
            if attempt == attempts:
                root_logger.debug("Maximum number of attempts (%d) reached"
                                  % attempts)
                return True
            root_logger.debug("Waiting 5 seconds before next retry")
            time.sleep(5)
        finally:
            if old_config is not None:
                os.environ['KRB5_CONFIG'] = old_config
            else:
                os.environ.pop('KRB5_CONFIG', None)

