def ba_handler_authenticate(http_environ, start_response, args_extra):
    """
    Try to authenticate user using JSON request-data.
    """
    params = http_environ['params']
    try:
        req_username = params['username']
        req_password = params['password']
    except KeyError:
        return (200, None, { 'error' : 'Username and/or password missing' })
    try:
        db_conn = ba_db_connect()
    except:
        return (200, None, { 'error': 'Database communication error' })
    if (ba_req_input_check_username(req_username) != True):
        return (200, None, { 'error': 'Username is not acceptable' })
    try:
        db_cursor = db_conn.cursor()
        db_cursor.execute(
            'SELECT username, password_hashed, salt FROM accounts WHERE username = %s AND enabled = 1',
            [req_username]
        )
    except:
        return (200, None, { 'error': 'Database communication error' })
    try:
        db_account_info = db_cursor.fetchmany(1)
        db_cursor.close()
    except:
        return (200, None, { 'error': 'Database communication error' })
    if (len(db_account_info) == 1):
        auth_ok = ba_req_input_password_verify(
            req_password,
            db_account_info[0][1],
            db_account_info[0][2]
        )
        if (auth_ok == True):
            return (200, None, { 'status': 1, 'authenticated': auth_ok })
    return (200, None, { 'error': 'Access denied' })

