def login_and_get_user(server, username, password):
    if not username:
        username = input('Email address: ')
    if not password:
        import getpass
        password = getpass.getpass('Password: ')
    hdr = {"PASSWORD": password, "Content-Type": "application/json"}
    r1 = requests.get(server + "/cloud/json/login", params={"username": username}, headers=hdr)
    j1 = json.loads(r1.text)
    check_response(j1)
    key = j1['key']
    hdr = {"PRESENCE_API_KEY": key, "Content-Type": "application/json"}
    r2 = requests.get(server + "/cloud/json/user", headers=hdr)
    j2 = json.loads(r2.text)
    check_response(j2)
    return key, j2

