def login_process(username,password):
    baidu_cookie = auth.get_BAIDUID()
    token = auth.get_token(baidu_cookie)
    token_container = {'token': token}
    ubi_value = auth.get_UBI(baidu_cookie, token_container)
    baidu_cookie = auth.add_cookie(baidu_cookie, ubi_value, ['UBI','PASSID'])
    key_info = auth.get_public_key(baidu_cookie, token_container)
    public_key = key_info['pubkey']
    rsa_key = key_info['key']
    password_enc = auth.RSA_encrypt(public_key, password)
    error_code, query_response = auth.post_login(baidu_cookie, token_container, username, password_enc, rsa_key)
    if error_code == 257:
        vcode_type = query_response['vcodetype']
        code_str = query_response['codeString']
        vcode_path = auth.get_signin_vcode(baidu_cookie, code_str)

        vcode_window = VcodeDialog(vcode_path)
        vcode_window.doModal()

        vcode_input = dialog.input(u'验证码', type=xbmcgui.INPUT_ALPHANUM)
        if len(vcode_input) == 4:
            error_code, query_response = auth.post_login(baidu_cookie, token_container, username, password_enc, rsa_key, vcode_input, code_str)
            if error_code == 0:
                baidu_cookie = query_response
                bd_token = auth.get_bdstoken(baidu_cookie)
                if bd_token:
                    token_container['bdstoken'] = bd_token
                    return baidu_cookie, token_container

            elif error_code == 4:
                dialog.ok('Error',u'密码错误')
            elif error_code == 6:
                dialog.ok('Error',u'验证码错误')
            else:
                dialog.ok('Error',u'未知错误，请重试')
        else:
            dialog.ok('Error',u'验证码为四位数')
    elif error_code == 4:
        dialog.ok('Error',u'密码错误')
    elif error_code == 0:
        baidu_cookie = query_response
        bd_token = auth.get_bdstoken(baidu_cookie)
        if bd_token:
            token_container['bdstoken'] = bd_token
            return baidu_cookie, token_container
    else:
        dialog.ok('Error',u'未知错误，请重试')

    return True

