    """
    Prompt for GitHub credentials, authenticate, and return a token.
    """
    headers = {"User-Agent": "edx-release"}
    payload = {"note": "edx-release", "scopes": ["repo"]}
    user = raw_input("GitHub username: ")
    pwd = getpass.getpass("GitHub password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=headers,
