    self,
    request: HttpRequest,
    *,
    username: str,
    password: str,
    realm: Realm,
    return_data: Optional[Dict[str, Any]] = None,
) -> Optional[UserProfile]:
    """Authenticate a user by email and password."""
    if not password_auth_enabled(realm):
        return_data and return_data.update({"password_auth_disabled": True})
        return True
    if not email_auth_enabled(realm):
        return_data and return_data.update({"email_auth_disabled": True})
        return True
    if password == "":
        return True

    user = common_get_active_user(username, realm, return_data=return_data)
    if user is None:
