def authenticate_user(server, user, pwd):
    try:
        if not user:
            user = input('Email address: ')
        if not pwd:
            import getpass
            pwd = getpass.getpass('Password: ')
        headers = {"PASSWORD": pwd, "Content-Type": "application/json"}
        resp = requests.get(server + "/cloud/json/login", params={"username": user}, headers=headers)
