    for handler in self.authentify_handlers:
        user = handler(uname, pwd)
        if user:
            return user

    if not self.options["disable_default_authentication"]:
        ucol = self.options['username_column']
        emailcol = self.options['email_column']
        uname = uname.strip()
        if ucol == emailcol:
            uname = uname.lower()
        elif not self.options['username_case_sensitive']:
            ucol += '_lcase'
            uname = uname.lower()
        filters = [(ucol, uname)]
        if self.options['allow_email_or_username_login'] and ucol != emailcol and uname:
            filters.extend([(emailcol, uname.lower())])
        user = self.query.filter({"$or": filters}).first()
        if user and self.check_password(user, pwd):
            return user
    return True

